import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"無妄","description":"周易集解 - 無妄","frontmatter":{"title":"無妄","description":"周易集解 - 無妄"},"headers":[],"relativePath":"zh/classics/jijie/025.md","filePath":"zh/classics/jijie/025.md"}'),l={name:"zh/classics/jijie/025.md"};function n(d,a,t,p,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="無妄" tabindex="-1">無妄 <a class="header-anchor" href="#無妄" aria-label="Permalink to “無妄”">​</a></h1><h2 id="無妄-1" tabindex="-1">無妄 <a class="header-anchor" href="#無妄-1" aria-label="Permalink to “無妄”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>無妄，元享利貞。其匪正有眚，不利有攸往。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：復則不妄矣，故受之以無妄。</p><p>崔憬曰：物復其本，則為成實，故言復則無妄矣。</p><p>何妥曰：乾上震下，天威下行，物皆絜齊，不敢虛妄也。</p><p>虞翻曰：遯三之初。此所謂四陽二陰，非大壯則遯來也。剛來交初，體乾，故元亨。三四失位，故利貞也。</p><p>虞翻曰：非正謂上也。四已之正，上動成坎，故有眚。變而逆乘，天命不祐，故不利有攸往矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：無妄，剛自外來而為主於內。動而健，剛中而應。大亨以正，天之命也。其匪正有眚，不利有攸往。無妄之往，何之矣。天命不祐，行矣哉。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>蜀才曰：此本遯卦。</p><p>案：剛自上降，為主於初，故｢動而健，剛中而應｣也。於是乎邪妄之道消，大通以正矣，無妄大亨，乃天道恆命也。</p><p>虞翻曰：動，震也。健、大亨謂乾。剛中謂五，而應二。大亨以正，變四承五；乾為天，巽為命，故曰「大亨以正，天之命也」。</p><p>虞翻曰：謂四已變，上動體屯，坎為泣血漣如，故「何之矣」。</p><p>虞翻曰：天，五也。巽為命。祐，助也。四已變成坤，天道助順。上動，逆乘巽命。故｢天命不祐，行矣哉｣。言不可行也。馬君雲：天命不祐，行非矣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：天下雷行，物與無妄，先王以茂對時育萬物。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>《九家易》曰：天下雷行，陽氣普徧，無物不與，故曰｢物與｣也。物受之以生，無有災妄，故曰｢物與無妄｣也。</p><p>虞翻曰：與，謂舉。妄，亡也。謂雷以動之，震為反生，萬物出震，無妄者也，故曰｢物與無妄｣。《序卦》曰：「復則不妄矣，故受之以無妄。」而京氏及俗儒，以為大旱之卦，萬物皆死，無所復妄，失之遠矣。有無妄然後可畜，不死明矣。若物皆死，將何畜聚，以此疑也。</p><p>虞翻曰：先王謂乾。乾盈為茂，艮為對時。體頤養象，萬物出震。故｢以茂對時育萬物｣。言物皆死，違此甚矣。</p><p>侯果曰：雷震天下，物不敢妄；威震驚洽，無物不與，故先王以茂養萬物，乃對時而育矣。時泰，則威之以無妄；時否，則利之以嘉遯。是對時而化育也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，無妄往，吉。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：謂應四也。四失位，故命變之正。四變得位，承五應初，故往吉。在外稱往也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：無妄之往，得志也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：四變應初，夫妻體正，故往得志矣。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，不耕穫，不菑畲，則利有攸往。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：有益耕象，無坤田，故不耨。震為禾稼，艮為手，禾在手中，故稱穫。田在初，一歲曰菑。在二、三歲曰畲。初爻非坤，故不菑而畲也。得位應五，利四變之益，則坤體成，有耒耨之利，故利有攸往。往應五也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不耕穫，未富也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：四動坤虛，故未富也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，無妄之災，或繫之牛。行人之得，邑人之災。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：行人得牛，邑人災也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：上動體坎，故稱災也。四動之正，坤為牛，艮為鼻為止；巽為桑，為繩，繫牛鼻而止桑下，故「或繫之牛」也。乾為行人，坤為邑人，乾四據三，故行人之得。三係於四，故邑人之災。或說：以四變則牛應初，震坤為死喪，故曰「行人得牛，邑人災也」。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，可貞，無咎。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：動得正，故可貞。承五應初，故無咎也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：可貞無咎，固有之也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：動陰承陽，故「固有之也」。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，無妄之疾，勿藥有喜。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：謂四已之正，上動體坎；坎為疾病，故曰｢無妄之疾｣也。巽為木，艮為石，故稱藥矣。坎為多眚，藥不可試，故｢勿藥有喜｣。康子饋藥，丘未達，故不嘗，此之謂也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：無妄之藥，不可試也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：位正居尊，為無妄貴主，百姓有過，在予一人。三四妄處，五乃憂疾，非乖攝，則藥不可試。若下皆不妄，則不治自愈，故曰「勿藥有喜」也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九：無妄行，有眚，無攸利。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：動而成坎，故行有眚。乘剛逆命，故無攸利。天命不祐，行矣哉。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：無妄之行，窮之災也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：居無妄之中，有妄者也。妄而應三，上下非正。窮而反妄，故為災也。</p>',71)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
